insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-02','en-c1-02',null,5,2,'published',1,'{"id":"en-c1-02","baseId":"en-c1-02","revision":1,"level":"C1","levelIndex":5,"order":2,"title":"Negative adverbialdan keyingi inversion","objective":"Cheklov va ta’kidni inversion bilan maqsadli ifodalaysiz.","context":"Negative adverbialdan keyingi inversion","prerequisites":["en-c1-01"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin.","Not until bilan inversion asosiy gapda: Not until … did we understand.","Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang."],"pattern":"Rarely have … / Not until … did …","examples":["Rarely have we seen such agreement.","Never had the group discussed access so carefully.","Under no circumstances should names be published.","Not until the review did we understand the limitation.","Only after consultation did they revise the plan.","No sooner had we begun than the alarm sounded."],"vocabulary":[{"id":"en-c1-02-v0","term":"restriction","meaning":"cheklov","ipa":"/rɪˈstrɪkʃən/","collocation":"state a restriction","example":"A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction."},{"id":"en-c1-02-v1","term":"emphasis","meaning":"ta’kid","ipa":"/ˈemfəsɪs/","collocation":"place emphasis","example":"A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended."},{"id":"en-c1-02-v2","term":"exception","meaning":"istisno","ipa":"/ɪkˈsepʃən/","collocation":"a rare exception","example":"a rare exception"},{"id":"en-c1-02-v3","term":"safeguard","meaning":"himoya chorasi","ipa":"/ˈseɪfɡɑːd/","collocation":"a privacy safeguard","example":"a privacy safeguard"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["Rarely have … / Not until … did …","Rarely have we seen such agreement.","Never had the group discussed access so carefully."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["Emphasis needs a defined scope.","Six participants agreed at one seminar.","Keep strong wording for justified observations and rules."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Not until the review did we understand the limitation.","audio":"/english-course/v7.23/en-c1-02-dictation.mp3"},"exercises":[{"id":"en-c1-02-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","options":["have","has","had"]},{"id":"en-c1-02-gap","type":"grammarFill","skill":"grammar","prompt":"Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["Rarely have we seen such agreement."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Rarely","have","we","seen","such","agreement."]},{"id":"en-c1-02-fix","type":"correction","skill":"grammar","prompt":"Rarely we have seen such agreement.","answers":["Rarely have we seen such agreement."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["cheklov","ta’kid","istisno","himoya chorasi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"Rarely have … / Not until … did …","left":["restriction","emphasis","exception","safeguard"],"options":["cheklov","ta’kid","istisno","himoya chorasi"]},{"id":"en-c1-02-transform","type":"transformation","skill":"grammar","prompt":"Only after boshida: They revised the plan only after consultation.","answers":["Only after consultation did they revise the plan."],"hint":"Rarely have … / Not until … did …","explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin."},{"id":"en-c1-02-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["Emphasis needs a defined scope.","Six participants agreed at one seminar.","Keep strong wording for justified observations and rules."],"answers":["Emphasis needs a defined scope.\nSix participants agreed at one seminar.\nKeep strong wording for justified observations and rules."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended. The claim is therefore about this seminar history, not a universal pattern. A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction. The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation. Advanced grammar earns its place when it supports a communicative purpose. A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters. Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants.","sentences":["A seminar summary opens, “Rarely have participants agreed so quickly.","” The sentence creates emphasis, but the writer later reveals that only six people attended.","The claim is therefore about this seminar history, not a universal pattern.","A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.","” Here inversion highlights an operational rule rather than an emotional reaction.","The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation.","Advanced grammar earns its place when it supports a communicative purpose.","A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters.","Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants."],"questions":[{"id":"en-c1-02-reading0","type":"choice","skill":"reading","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-reading1","type":"choice","skill":"reading","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]},{"id":"en-c1-02-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"Rarely have … / Not until … did …","options":["A seminar summary opens, “Rarely have participants agreed so quickly.","” The sentence creates emphasis, but the writer later reveals that only six people attended.","The claim is therefore about this seminar history, not a universal pattern.","A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.","” Here inversion highlights an operational rule rather than an emotional reaction.","The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation.","Advanced grammar earns its place when it supports a communicative purpose.","A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters.","Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is restriction. A seminar summary opens, “Rarely have participants agreed so quickly. ” The sentence creates emphasis, but the writer later reveals that only six people attended. Speaker two: My main point is purpose. Use inversion when the communicative purpose justifies the emphasis. A seminar summary opens, “Rarely have participants agreed so quickly.” The sentence creates emphasis, but the writer later reveals that only six people attended. The claim is therefore about this seminar history, not a universal pattern. A privacy note uses a stronger restriction: “Under no circumstances should names be published without permission.” Here inversion highlights an operational rule rather than an emotional reaction. The editor keeps that emphasis and simplifies a third inverted sentence because it interrupts the explanation. Advanced grammar earns its place when it supports a communicative purpose. A reader should be able to say what is being restricted, when understanding changed, or why emphasis matters. Unnecessary inversion can make ordinary information sound more dramatic than its evidence warrants.","audio":"/english-course/v7.23/en-c1-02.mp3","synthetic":true,"questions":[{"id":"en-c1-02-listening0","type":"choice","skill":"listening","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-listening1","type":"choice","skill":"listening","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]},{"id":"en-c1-02-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["restriction","purpose"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"Rarely have … / Not until … did …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-02-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Not until the review did we understand the limitation."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"Rarely have … / Not until … did …","audio":"/english-course/v7.23/en-c1-02-dictation.mp3","transcript":"Not until the review did we understand the limitation."}]},"writing":{"task":"Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"Rarely have participants reached agreement so quickly, although the meeting involved only six people. The result should therefore be interpreted within that limited setting. Only after consultation did the committee revise the access criteria. This emphasis highlights the sequence that made the revision possible. Under no circumstances should participants’ names be published without permission. Unlike the opening observation, this final sentence states a restriction, so its strong emphasis serves a practical purpose rather than exaggerating the findings.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["Rarely have we seen such agreement.","Never had the group discussed access so carefully.","Under no circumstances should names be published."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Seminar summary yozing; ikkita inversion va ularning vazifasini alohida izohlang.","exit":[[{"id":"en-c1-02-exit0","type":"grammarFill","skill":"grammar","prompt":"Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit1","type":"grammarFill","skill":"grammar","prompt":"Not until the review ___ we understand.","answers":["did"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit2","type":"grammarFill","skill":"grammar","prompt":"Under no circumstances ___ names be published.","answers":["should"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit3","type":"choice","skill":"grammar","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-exit4","type":"choice","skill":"grammar","prompt":"Editor nega bir gapni soddalashtirdi?","answers":["its emphasis obstructed explanation"],"explanation":"Maqsadsiz ta’kid o‘qishga halal.","hint":"Rarely have … / Not until … did …","options":["its emphasis obstructed explanation","inversion is always wrong","all information was false"]}],[{"id":"en-c1-02-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Never had the group discussed access so carefully."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Never","had","the","group","discussed","access","so","carefully."]},{"id":"en-c1-02-exit-b1","type":"grammarFill","skill":"grammar","prompt":"Not until the review ___ we understand.","answers":["did"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …"},{"id":"en-c1-02-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Not until the review did we understand the limitation."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["Not","until","the","review","did","we","understand","the","limitation."]},{"id":"en-c1-02-exit-b3","type":"choice","skill":"grammar","prompt":"Privacy inversion vazifasi?","answers":["highlight an operational restriction"],"explanation":"Qoidani ta’kidlaydi.","hint":"Rarely have … / Not until … did …","options":["highlight an operational restriction","prove a universal survey result","describe six names"]},{"id":"en-c1-02-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["No sooner had we begun than the alarm sounded."],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","tokens":["No","sooner","had","we","begun","than","the","alarm","sounded."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-02","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-03','en-c1-03',null,5,3,'published',1,'{"id":"en-c1-03","baseId":"en-c1-03","revision":1,"level":"C1","levelIndex":5,"order":3,"title":"Cleft va pseudo-cleft","objective":"Yangi yoki tuzatiladigan ma’lumotni fokusga chiqarasiz.","context":"Cleft va pseudo-cleft","prerequisites":["en-c1-02"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["It was X that … fokusni Xga qo‘yadi.","What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi.","Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi."],"pattern":"It was access that … / What we need is …","examples":["It was access that concerned the students.","What we need is a clearer timetable.","It was not the price that caused the disagreement.","What the survey reveals is a gap in communication.","The reason we paused was the missing evidence.","It was only after the interview that the issue became clear."],"vocabulary":[{"id":"en-c1-03-v0","term":"focus","meaning":"markaziy e’tibor","ipa":"/ˈfəʊkəs/","collocation":"shift the focus","example":"The writer uses a cleft to correct the mistaken focus without claiming that price was irrelevant."},{"id":"en-c1-03-v1","term":"misconception","meaning":"noto‘g‘ri tasavvur","ipa":"/ˌmɪskənˈsepʃən/","collocation":"correct a misconception","example":"correct a misconception"},{"id":"en-c1-03-v2","term":"exclusive","meaning":"faqat shu","ipa":"/ɪkˈskluːsɪv/","collocation":"an exclusive claim","example":"an exclusive claim"},{"id":"en-c1-03-v3","term":"clarification","meaning":"aniqlashtirish","ipa":"/ˌklærɪfɪˈkeɪʃən/","collocation":"request clarification","example":"request clarification"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["It was access that … / What we need is …","It was access that concerned the students.","What we need is a clearer timetable."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The original summary focused on price.","Interviews identified travel constraints.","Shift the focus while preserving other factors."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"What the survey reveals is a gap in communication.","audio":"/english-course/v7.23/en-c1-03-dictation.mp3"},"exercises":[{"id":"en-c1-03-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: It was access ___ concerned them.","answers":["that"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","options":["that","what","who"]},{"id":"en-c1-03-gap","type":"grammarFill","skill":"grammar","prompt":"It was access ___ concerned them.","answers":["that"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["It was access that concerned the students."],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","tokens":["It","was","access","that","concerned","the","students."]},{"id":"en-c1-03-fix","type":"correction","skill":"grammar","prompt":"What we need are a clearer timetable.","answers":["What we need is a clearer timetable."],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["markaziy e’tibor","noto‘g‘ri tasavvur","faqat shu","aniqlashtirish"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"It was access that … / What we need is …","left":["focus","misconception","exclusive","clarification"],"options":["markaziy e’tibor","noto‘g‘ri tasavvur","faqat shu","aniqlashtirish"]},{"id":"en-c1-03-transform","type":"transformation","skill":"grammar","prompt":"Accessga fokus: Access concerned the students.","answers":["It was access that concerned the students."],"hint":"It was access that … / What we need is …","explanation":"It was X that … fokusni Xga qo‘yadi."},{"id":"en-c1-03-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The original summary focused on price.","Interviews identified travel constraints.","Shift the focus while preserving other factors."],"answers":["The original summary focused on price.\nInterviews identified travel constraints.\nShift the focus while preserving other factors."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-03-collocations","type":"collocation","skill":"vocabulary","prompt":"So‘zlarni darsdagi birikmasi bilan moslang.","left":["focus","misconception","exclusive","clarification"],"options":["shift the focus","correct a misconception","an exclusive claim","request clarification"],"answers":["shift the focus","correct a misconception","an exclusive claim","request clarification"],"hint":"So‘z qaysi birikmada ishlatilishini eslang.","explanation":"Birikmani yozgan gapingizda ham ishlating."}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"A debate is described as an argument about price. The interviews show something more specific: it was access that concerned the students most. Price mattered, but travel time prevented some students from attending even a free session. The writer uses a cleft to correct the mistaken focus without claiming that price was irrelevant. She then adds, “What we need is a clearer timetable.” This pseudo-cleft moves from diagnosis to a practical request. A revised sentence saying “Only access mattered” would go further than the evidence. Focusing information is not the same as excluding every other factor. Good editing preserves that distinction and helps readers notice the central issue while retaining the complexity of the original discussion.","sentences":["A debate is described as an argument about price.","The interviews show something more specific: it was access that concerned the students most.","Price mattered, but travel time prevented some students from attending even a free session.","The writer uses a cleft to correct the mistaken focus without claiming that price was irrelevant.","She then adds, “What we need is a clearer timetable.","” This pseudo-cleft moves from diagnosis to a practical request.","A revised sentence saying “Only access mattered” would go further than the evidence.","Focusing information is not the same as excluding every other factor.","Good editing preserves that distinction and helps readers notice the central issue while retaining the complexity of the original discussion."],"questions":[{"id":"en-c1-03-reading0","type":"choice","skill":"reading","prompt":"Markaziy muammo?","answers":["access"],"explanation":"Travel attendancega to‘siq.","hint":"It was access that … / What we need is …","options":["access","price alone","no timetable ever existed"]},{"id":"en-c1-03-reading1","type":"choice","skill":"reading","prompt":"Only access nega haddan tashqari?","answers":["price still mattered"],"explanation":"Fokus boshqa omilni rad etmaydi.","hint":"It was access that … / What we need is …","options":["price still mattered","access was irrelevant","all sessions were free"]},{"id":"en-c1-03-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"It was access that … / What we need is …","options":["A debate is described as an argument about price.","The interviews show something more specific: it was access that concerned the students most.","Price mattered, but travel time prevented some students from attending even a free session.","The writer uses a cleft to correct the mistaken focus without claiming that price was irrelevant.","She then adds, “What we need is a clearer timetable.","” This pseudo-cleft moves from diagnosis to a practical request.","A revised sentence saying “Only access mattered” would go further than the evidence.","Focusing information is not the same as excluding every other factor.","Good editing preserves that distinction and helps readers notice the central issue while retaining the complexity of the original discussion."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is focus. A debate is described as an argument about price. The interviews show something more specific: it was access that concerned the students most. Speaker two: My main point is complexity. Correct the focus without excluding every other relevant factor. A debate is described as an argument about price. The interviews show something more specific: it was access that concerned the students most. Price mattered, but travel time prevented some students from attending even a free session. The writer uses a cleft to correct the mistaken focus without claiming that price was irrelevant. She then adds, “What we need is a clearer timetable.” This pseudo-cleft moves from diagnosis to a practical request. A revised sentence saying “Only access mattered” would go further than the evidence. Focusing information is not the same as excluding every other factor. Good editing preserves that distinction and helps readers notice the central issue while retaining the complexity of the original discussion.","audio":"/english-course/v7.23/en-c1-03.mp3","synthetic":true,"questions":[{"id":"en-c1-03-listening0","type":"choice","skill":"listening","prompt":"Markaziy muammo?","answers":["access"],"explanation":"Travel attendancega to‘siq.","hint":"It was access that … / What we need is …","options":["access","price alone","no timetable ever existed"]},{"id":"en-c1-03-listening1","type":"choice","skill":"listening","prompt":"Only access nega haddan tashqari?","answers":["price still mattered"],"explanation":"Fokus boshqa omilni rad etmaydi.","hint":"It was access that … / What we need is …","options":["price still mattered","access was irrelevant","all sessions were free"]},{"id":"en-c1-03-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["focus","complexity"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"It was access that … / What we need is …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-03-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["What the survey reveals is a gap in communication."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"It was access that … / What we need is …","audio":"/english-course/v7.23/en-c1-03-dictation.mp3","transcript":"What the survey reveals is a gap in communication."}]},"writing":{"task":"Noto‘g‘ri talqin qilingan munozarani cleft va pseudo-cleft bilan aniqlashtiring.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"It was access that concerned the students most. Although price was discussed, some participants could not attend even a free session because the journey was too long. What we need is a timetable that makes those constraints visible. The report should not imply that only access mattered; that would replace one oversimplification with another. A focused explanation can identify the central issue while acknowledging the factors that remain relevant to the decision.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["It was access that concerned the students.","What we need is a clearer timetable.","It was not the price that caused the disagreement."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Noto‘g‘ri talqin qilingan munozarani cleft va pseudo-cleft bilan aniqlashtiring. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Noto‘g‘ri talqin qilingan munozarani cleft va pseudo-cleft bilan aniqlashtiring.","exit":[[{"id":"en-c1-03-exit0","type":"grammarFill","skill":"grammar","prompt":"It was access ___ concerned them.","answers":["that"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-exit1","type":"grammarFill","skill":"grammar","prompt":"What we need ___ a timetable.","answers":["is"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-exit2","type":"grammarFill","skill":"grammar","prompt":"It was not the price ___ caused disagreement.","answers":["that"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-exit3","type":"choice","skill":"grammar","prompt":"Markaziy muammo?","answers":["access"],"explanation":"Travel attendancega to‘siq.","hint":"It was access that … / What we need is …","options":["access","price alone","no timetable ever existed"]},{"id":"en-c1-03-exit4","type":"choice","skill":"grammar","prompt":"Only access nega haddan tashqari?","answers":["price still mattered"],"explanation":"Fokus boshqa omilni rad etmaydi.","hint":"It was access that … / What we need is …","options":["price still mattered","access was irrelevant","all sessions were free"]}],[{"id":"en-c1-03-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["What we need is a clearer timetable."],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","tokens":["What","we","need","is","a","clearer","timetable."]},{"id":"en-c1-03-exit-b1","type":"grammarFill","skill":"grammar","prompt":"What we need ___ a timetable.","answers":["is"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …"},{"id":"en-c1-03-exit-b2","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["What the survey reveals is a gap in communication."],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","tokens":["What","the","survey","reveals","is","a","gap","in","communication."]},{"id":"en-c1-03-exit-b3","type":"choice","skill":"grammar","prompt":"Markaziy muammo?","answers":["access"],"explanation":"Travel attendancega to‘siq.","hint":"It was access that … / What we need is …","options":["access","price alone","no timetable ever existed"]},{"id":"en-c1-03-exit-b4","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["It was only after the interview that the issue became clear."],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","tokens":["It","was","only","after","the","interview","that","the","issue","became","clear."]}]],"sources":[{"id":"cefr","name":"Council of Europe — CEFR daraja tavsiflari","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"framework","url":"https://www.coe.int/en/web/common-european-framework-reference-languages/level-descriptions","task":"Dars maqsadini qila olaman tavsifi bilan solishtiring. PRE — kursning tayyorlov bosqichi.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"pronunciation","name":"Cambridge Dictionary — Pronunciation","levels":["PRE","A1","A2","B1","B2","C1"],"skill":"pronunciation","url":"https://dictionary.cambridge.org/pronunciation/","task":"Darsdan ikki so‘z tanlang, UK/US talaffuzini eshiting va urg‘uni qayd eting.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-grammar","name":"British Council — Grammar","levels":["A1","A2","B1","B2","C1"],"skill":"grammar","url":"https://learnenglish.britishcouncil.org/free-resources/grammar","task":"Darajangizdagi dars mavzusini toping va bitta o‘xshash misol yozing.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-read","name":"British Council — Reading","levels":["A1","A2","B1","B2","C1"],"skill":"reading","url":"https://learnenglish.britishcouncil.org/free-resources/reading","task":"O‘z darajangizdagi matnni tanlang; asosiy fikr va bitta dalilni ajrating.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-write","name":"British Council — Writing","levels":["A1","A2","B1","B2","C1"],"skill":"writing","url":"https://learnenglish.britishcouncil.org/free-resources/writing","task":"Darajangizdagi namunaning kirish, asosiy qism va yakunini tahlil qiling.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"bc-listen","name":"British Council — Listening (A1–C1)","levels":["A1","A2","B1","B2","C1"],"skill":"listening","url":"https://learnenglish.britishcouncil.org/free-resources/listening","task":"Mos daraja audiosini transkriptsiz tinglang; keyin yozuv bilan tekshiring.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"cambridge","name":"Cambridge English — Activities","levels":["A1","A2","B1","B2","C1"],"skill":"integrated","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/","task":"A1–A2, B1–B2 yoki C1–C2 filtrini qo‘llang; dars ko‘nikmasiga mos mashqni tanlang.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."},{"id":"c1-natural","name":"Cambridge English — Bank accounts (C1–C2)","levels":["C1"],"skill":"listening","url":"https://www.cambridgeenglish.org/learning-english/activities-for-learners/c1l062-bank-accounts","task":"Tabiiy nutqdagi maqsad va muhim shartlarni tinglab, qisqa xulosa yozing.","lesson":"en-c1-03","verified":"2026-10-05","mode":"link","rights":"Manba saytida bajariladi; himoyalangan matn yoki audio ko‘chirilmagan."}],"recapEvery":4,"project":false,"rights":"Original SinfQuiz content; local Flite synthetic speech. Educational references are linked, not copied."}'::jsonb) on conflict(id,revision) do nothing;
insert into public.sq_en_content(id,base_id,owner_id,level,ordinal,status,revision,payload) values('en-c1-04','en-c1-04',null,5,4,'published',1,'{"id":"en-c1-04","baseId":"en-c1-04","revision":1,"level":"C1","levelIndex":5,"order":4,"title":"Fronting va information structure","objective":"Mavzudan yangi ma’lumotga o‘tishni mantiqiy tuzasiz.","context":"Fronting va information structure","prerequisites":["en-c1-03"],"minutes":55,"skills":["grammar","vocabulary","pronunciation","listening","reading","writing","speaking"],"rules":["Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi.","Fronting har doim inversion talab qilmaydi: This question, we can answer.","Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi."],"pattern":"This limitation, we can address. / Of greater concern is …","examples":["This limitation, we can address.","Of greater concern is the missing comparison group.","The first option we have already discussed.","Into the room came the organiser.","What remains uncertain is the long-term effect.","The next section examines that uncertainty."],"vocabulary":[{"id":"en-c1-04-v0","term":"coherence","meaning":"mantiqiy yaxlitlik","ipa":"/kəʊˈhɪərəns/","collocation":"improve coherence","example":"Fronting can improve coherence, but it is not a decoration that every sentence requires."},{"id":"en-c1-04-v1","term":"foreground","meaning":"markazga chiqarish","ipa":"/ˈfɔːɡraʊnd/","collocation":"foreground a limitation","example":"foreground a limitation"},{"id":"en-c1-04-v2","term":"transition","meaning":"o‘tish","ipa":"/trænˈzɪʃən/","collocation":"a clear transition","example":"Readers lose the connection because the new topic appears without a transition."},{"id":"en-c1-04-v3","term":"salient","meaning":"muhim ajraluvchi","ipa":"/ˈseɪliənt/","collocation":"a salient point","example":"a salient point"}],"visuals":[{"kind":"argument","title":"Ma’no va tuzilish","items":["This limitation, we can address. / Of greater concern is …","This limitation, we can address.","Of greater concern is the missing comparison group."]},{"kind":"argument","title":"Fikr va dalilning aloqasi","items":["The sample limitation is already known.","A comparison group is also missing.","Move from one uncertainty to the next with a clear transition."]}],"pronunciation":{"focus":"Gapdagi mazmunli so‘zlarni urg‘u bilan ayting. Nuqtada to‘xtab, yozuvni qayta tinglang.","text":"Into the room came the organiser.","audio":"/english-course/v7.23/en-c1-04-dictation.mp3"},"exercises":[{"id":"en-c1-04-choice","type":"choice","skill":"grammar","prompt":"Til vositasini tanlang: Of greater concern ___ the missing group.","answers":["is"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …","options":["is","are","being"]},{"id":"en-c1-04-gap","type":"grammarFill","skill":"grammar","prompt":"Of greater concern ___ the missing group.","answers":["is"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-order","type":"order","skill":"grammar","prompt":"Kartalarni to‘g‘ri tartibga qo‘ying.","answers":["This limitation, we can address."],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …","tokens":["This","limitation,","we","can","address."]},{"id":"en-c1-04-fix","type":"correction","skill":"grammar","prompt":"This question, can we answer. (tasdiq gap)","answers":["This question, we can answer."],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-vocabulary","type":"matching","skill":"vocabulary","prompt":"So‘zlarni ma’nolari bilan moslang.","answers":["mantiqiy yaxlitlik","markazga chiqarish","o‘tish","muhim ajraluvchi"],"explanation":"So‘zni alohida emas, darsdagi birikma va gap bilan eslang.","hint":"This limitation, we can address. / Of greater concern is …","left":["coherence","foreground","transition","salient"],"options":["mantiqiy yaxlitlik","markazga chiqarish","o‘tish","muhim ajraluvchi"]},{"id":"en-c1-04-transform","type":"transformation","skill":"grammar","prompt":"Questionni topic qiling: We can answer this question.","answers":["This question, we can answer."],"hint":"This limitation, we can address. / Of greater concern is …","explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi."},{"id":"en-c1-04-paragraphs","type":"paragraphOrder","skill":"reading","prompt":"Fikrni tartiblang: da’vo → dalil → talqin.","tokens":["The sample limitation is already known.","A comparison group is also missing.","Move from one uncertainty to the next with a clear transition."],"answers":["The sample limitation is already known.\nA comparison group is also missing.\nMove from one uncertainty to the next with a clear transition."],"hint":"Da’vo nimani aytadi? Dalil nimani ko‘rsatadi?","explanation":"Dalil yakuniy xulosaning o‘rnini bosmaydi; talqin ularning aloqasini tushuntiradi."},{"id":"en-c1-04-dialogue","type":"dialogue","skill":"grammar","prompt":"Sherik: “Can you give one example?” Siz: darsdagi birinchi namunani qayta tuzing.","answers":["This limitation, we can address."],"tokens":["This","limitation,","we","can","address."],"hint":"This limitation, we can address. / Of greater concern is …","explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi."},{"id":"en-c1-04-recap-0","type":"choice","skill":"grammar","prompt":"Takrorlash · Grammatik tanlov va muallif pozitsiyasi: Til vositasini tanlang: Criteria have been ___ twice. (revise)","answers":["revised"],"explanation":"Active agentni, passive jarayon yoki natijani markazga oladi; ikkalasi faktni buzmasligi kerak. Aspect davomiylik, natija va vaqt chegarasini belgilaydi. Grammatik shaklning ritorik ta’sirini dalil bilan izohlang, muallif niyatini taxmin bilan faktga aylantirmang.","hint":"the committee delayed / the decision was delayed / has been reconsidering","options":["revised","revising","revise"],"recap":true,"sourceLesson":"Grammatik tanlov va muallif pozitsiyasi"},{"id":"en-c1-04-recap-1","type":"choice","skill":"grammar","prompt":"Takrorlash · Negative adverbialdan keyingi inversion: Til vositasini tanlang: Rarely ___ we seen such agreement.","answers":["have"],"explanation":"Never/rarely/seldom/under no circumstances boshida yordamchi fe’l egadan oldin. Not until bilan inversion asosiy gapda: Not until … did we understand. Inversion rasmiy ta’kid; har gapni bezash uchun qo‘llamang.","hint":"Rarely have … / Not until … did …","options":["have","has","had"],"recap":true,"sourceLesson":"Negative adverbialdan keyingi inversion"},{"id":"en-c1-04-recap-2","type":"choice","skill":"grammar","prompt":"Takrorlash · Cleft va pseudo-cleft: Til vositasini tanlang: It was access ___ concerned them.","answers":["that"],"explanation":"It was X that … fokusni Xga qo‘yadi. What we need is … pseudo-cleft oldingi vaziyatdan yangi talabga o‘tadi. Ta’kid faktning doirasini o‘zgartirmasin; only ishlatilsa eksklyuziv ma’no qo‘shadi.","hint":"It was access that … / What we need is …","options":["that","what","who"],"recap":true,"sourceLesson":"Cleft va pseudo-cleft"}],"reading":{"title":"Asosiy matn va muallif pozitsiyasi","text":"An analytical report first discusses a small sample, then unexpectedly begins a paragraph about long-term effects. Readers lose the connection because the new topic appears without a transition. The editor writes, “This limitation, we can address with a larger survey. Of greater concern is the missing comparison group.” The structure connects a known limitation to a more important uncertainty. Fronting can improve coherence, but it is not a decoration that every sentence requires. The editor also moves a long explanation to the end of a sentence so that readers meet familiar information before new detail. The revised report becomes easier to follow without reducing its complexity. Information structure helps organise attention, while evidence still determines whether the conclusions are justified.","sentences":["An analytical report first discusses a small sample, then unexpectedly begins a paragraph about long-term effects.","Readers lose the connection because the new topic appears without a transition.","The editor writes, “This limitation, we can address with a larger survey.","Of greater concern is the missing comparison group.","” The structure connects a known limitation to a more important uncertainty.","Fronting can improve coherence, but it is not a decoration that every sentence requires.","The editor also moves a long explanation to the end of a sentence so that readers meet familiar information before new detail.","The revised report becomes easier to follow without reducing its complexity.","Information structure helps organise attention, while evidence still determines whether the conclusions are justified."],"questions":[{"id":"en-c1-04-reading0","type":"choice","skill":"reading","prompt":"Yangi structure nima yaxshilaydi?","answers":["the connection between known and new information"],"explanation":"Tashkilot dalil yaratmaydi.","hint":"This limitation, we can address. / Of greater concern is …","options":["the connection between known and new information","the size of the sample","the evidence itself"]},{"id":"en-c1-04-reading1","type":"choice","skill":"reading","prompt":"Qaysi muammo muhimroq deyiladi?","answers":["the missing comparison group"],"explanation":"Of greater concern.","hint":"This limitation, we can address. / Of greater concern is …","options":["the missing comparison group","the font alone","a long sentence itself"]},{"id":"en-c1-04-evidence","type":"evidence","skill":"reading","prompt":"Vaziyatni tanishtiradigan birinchi jumlani tanlang.","answers":["0"],"explanation":"Birinchi jumla matn vaziyatini tanishtiradi; keyingi jumlalar uni rivojlantiradi.","hint":"This limitation, we can address. / Of greater concern is …","options":["An analytical report first discusses a small sample, then unexpectedly begins a paragraph about long-term effects.","Readers lose the connection because the new topic appears without a transition.","The editor writes, “This limitation, we can address with a larger survey.","Of greater concern is the missing comparison group.","” The structure connects a known limitation to a more important uncertainty.","Fronting can improve coherence, but it is not a decoration that every sentence requires.","The editor also moves a long explanation to the end of a sentence so that readers meet familiar information before new detail.","The revised report becomes easier to follow without reducing its complexity.","Information structure helps organise attention, while evidence still determines whether the conclusions are justified."]}]},"listening":{"title":"Boshqa nuqtayi nazarni tinglang","transcript":"Speaker one: Our key word is transition. An analytical report first discusses a small sample, then unexpectedly begins a paragraph about long-term effects. Readers lose the connection because the new topic appears without a transition. Speaker two: My main point is coherence. Connect familiar information to the next uncertainty before adding detail. An analytical report first discusses a small sample, then unexpectedly begins a paragraph about long-term effects. Readers lose the connection because the new topic appears without a transition. The editor writes, “This limitation, we can address with a larger survey. Of greater concern is the missing comparison group.” The structure connects a known limitation to a more important uncertainty. Fronting can improve coherence, but it is not a decoration that every sentence requires. The editor also moves a long explanation to the end of a sentence so that readers meet familiar information before new detail. The revised report becomes easier to follow without reducing its complexity. Information structure helps organise attention, while evidence still determines whether the conclusions are justified.","audio":"/english-course/v7.23/en-c1-04.mp3","synthetic":true,"questions":[{"id":"en-c1-04-listening0","type":"choice","skill":"listening","prompt":"Yangi structure nima yaxshilaydi?","answers":["the connection between known and new information"],"explanation":"Tashkilot dalil yaratmaydi.","hint":"This limitation, we can address. / Of greater concern is …","options":["the connection between known and new information","the size of the sample","the evidence itself"]},{"id":"en-c1-04-listening1","type":"choice","skill":"listening","prompt":"Qaysi muammo muhimroq deyiladi?","answers":["the missing comparison group"],"explanation":"Of greater concern.","hint":"This limitation, we can address. / Of greater concern is …","options":["the missing comparison group","the font alone","a long sentence itself"]},{"id":"en-c1-04-audio-table","type":"table","skill":"listening","prompt":"Tinglangan ma’lumotni jadvalga yozing.","answers":["transition","coherence"],"explanation":"Jadvaldagi javoblar yozuvda aynan aytilgan. Mavjud bo‘lmagan tafsilotni taxmin qilmang.","hint":"This limitation, we can address. / Of greater concern is …","rows":["Birinchi gapdagi asosiy so‘z","Sherikning asosiy fikri"]},{"id":"en-c1-04-dictation","type":"dictation","skill":"listening","prompt":"Eshitgan gapingizni yozing.","answers":["Into the room came the organiser."],"explanation":"Gapdagi asosiy so‘zlar, yordamchi fe’l va inkor saqlanishi kerak.","hint":"This limitation, we can address. / Of greater concern is …","audio":"/english-course/v7.23/en-c1-04-dictation.mp3","transcript":"Into the room came the organiser."}]},"writing":{"task":"Reportning uch paragrafini known→new zanjiri bilan yozing va transitionlarni belgilang.","audience":"Maktab kengashi yoki loyiha guruhi","minWords":70,"maxWords":420,"plan":["Da’vo va maqsadni aniqlang.","Reading va listeningdan bir dalilni qiyoslang.","Cheklov yoki qarshi fikrni tushuntiring.","Auditoriyaga mos amaliy xulosa yozing."],"model":"The small sample limits our confidence in the survey. This limitation, we can address by inviting a broader group of respondents. Of greater concern is the absence of a comparison group, because a larger sample alone would not explain what would have happened without the programme. The next section examines that uncertainty. Organising the information in this sequence makes the reasoning easier to follow, but it does not supply the missing evidence. The recommendation must remain proportionate to what the study actually shows.","modelNotes":["Kirishda auditoriya va maqsad aniq.","Asosiy qism dalilni talqin bilan bog‘laydi.","Yakun haddan tashqari umumlashtirmaydi."],"phrases":["This limitation, we can address.","Of greater concern is the missing comparison group.","The first option we have already discussed."],"checklist":["Topshiriq va auditoriyaga mos yozdim.","Fikrni o‘z so‘zlarim bilan ifodaladim.","Darsdagi shaklni to‘g‘ri ishlatdim.","Imlo, bog‘lanish va tinish belgilarini tekshirdim."]},"speaking":{"task":"Reading va listeningni taqqoslang. Reportning uch paragrafini known→new zanjiri bilan yozing va transitionlarni belgilang. Sherigingizning e’tiroziga javob bering.","seconds":150,"prompts":["Reading va listening qayerda mos, qayerda farqli?","Sherigingizning e’tiroziga javob bering.","Qaysi dalil xulosangizni o‘zgartirishi mumkin?"],"rubric":["Vazifani bajarish","Til vositalari va aniqlik","Bog‘langan, tushunarli nutq","Talaffuz va muloqot"]},"rubrics":{"writing":["Mazmun va vazifani bajarish","Tuzilish va bog‘lanish","Til vositalari va uslub","Grammatika va imlo"],"speaking":["Vazifa va o‘zaro muloqot","Ravonlik va bog‘lanish","Til vositalari va aniqlik","Tushunarlilik va talaffuz"]},"realTask":"Reportning uch paragrafini known→new zanjiri bilan yozing va transitionlarni belgilang.","exit":[[{"id":"en-c1-04-exit0","type":"grammarFill","skill":"grammar","prompt":"Of greater concern ___ the missing group.","answers":["is"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-exit1","type":"grammarFill","skill":"grammar","prompt":"The first option we have already ___. (discuss)","answers":["discussed"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-exit2","type":"grammarFill","skill":"grammar","prompt":"The next section ___ that uncertainty. (examine)","answers":["examines"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-exit3","type":"choice","skill":"grammar","prompt":"Yangi structure nima yaxshilaydi?","answers":["the connection between known and new information"],"explanation":"Tashkilot dalil yaratmaydi.","hint":"This limitation, we can address. / Of greater concern is …","options":["the connection between known and new information","the size of the sample","the evidence itself"]},{"id":"en-c1-04-exit4","type":"choice","skill":"grammar","prompt":"Qaysi muammo muhimroq deyiladi?","answers":["the missing comparison group"],"explanation":"Of greater concern.","hint":"This limitation, we can address. / Of greater concern is …","options":["the missing comparison group","the font alone","a long sentence itself"]}],[{"id":"en-c1-04-exit-b0","type":"order","skill":"grammar","prompt":"Gapni tartiblang.","answers":["Of greater concern is the missing comparison group."],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …","tokens":["Of","greater","concern","is","the","missing","comparison","group."]},{"id":"en-c1-04-exit-b1","type":"grammarFill","skill":"grammar","prompt":"The first option we have already ___. (discuss)","answers":["discussed"],"explanation":"Oldingi kontekstga bog‘langan bo‘lakni boshga chiqarish cohesionga xizmat qiladi. Fronting har doim inversion talab qilmaydi: This question, we can answer. Topic va focusni ajrating; uzun yangi ma’lumot odatda gap oxirida yengilroq o‘qiladi.","hint":"This limitation, we can address. / Of greater concern is …"},{"id":"en-c1-04-exit-b2","ty